// Regras do jogo: medalhas (dadas por professores), troféus (automáticos) e pontos.
// Para mudar pontos, nomes ou criar novos troféus, é só editar este arquivo.

export const POINTS = {
  post: 10, // por foto publicada
  postsPerDay: 3, // só as 3 primeiras fotos do dia valem pontos (evita spam)
  likeReceived: 2, // por curtida recebida de outra pessoa
};

export const MEDAL_TYPES = [
  { code: 'participacao', name: 'Participação', emoji: '🙋', points: 20, color: '#10b981', desc: 'Participou ativamente das aulas e atividades.' },
  { code: 'colaboracao', name: 'Colaboração', emoji: '🤝', points: 30, color: '#06b6d4', desc: 'Ajudou os colegas e fez a diferença no trabalho em equipe.' },
  { code: 'criatividade', name: 'Criatividade', emoji: '💡', points: 40, color: '#f59e0b', desc: 'Trouxe uma ideia original ou uma solução criativa.' },
  { code: 'lideranca', name: 'Liderança', emoji: '🧭', points: 50, color: '#8b5cf6', desc: 'Organizou, motivou e conduziu um grupo.' },
  { code: 'pesquisa', name: 'Pesquisa', emoji: '🔬', points: 60, color: '#3b82f6', desc: 'Destaque em iniciação científica, artigo ou projeto de pesquisa.' },
  { code: 'destaque', name: 'Destaque Acadêmico', emoji: '🏅', points: 80, color: '#ef4444', desc: 'Desempenho acima da média em uma disciplina.' },
  { code: 'excelencia', name: 'Excelência', emoji: '👑', points: 100, color: '#eab308', desc: 'Reconhecimento máximo: um trabalho exemplar.' },
];
export const MEDAL_BY_CODE = Object.fromEntries(MEDAL_TYPES.map((m) => [m.code, m]));

// stat = qual número do aluno é comparado com target.
export const TROPHIES = [
  { code: 'primeiro_clique', name: 'Primeiro clique', emoji: '📸', tier: 'bronze', stat: 'posts', target: 1, points: 15, desc: 'Publique sua primeira foto.' },
  { code: 'fotografo', name: 'Fotógrafo do campus', emoji: '🎞️', tier: 'prata', stat: 'posts', target: 10, points: 50, desc: 'Publique 10 fotos.' },
  { code: 'lente_de_ouro', name: 'Lente de ouro', emoji: '🔭', tier: 'ouro', stat: 'posts', target: 30, points: 120, desc: 'Publique 30 fotos.' },
  { code: 'curtido', name: 'Curtido', emoji: '❤️', tier: 'bronze', stat: 'likesReceived', target: 10, points: 30, desc: 'Receba 10 curtidas.' },
  { code: 'popular', name: 'Popular', emoji: '🔥', tier: 'prata', stat: 'likesReceived', target: 50, points: 80, desc: 'Receba 50 curtidas.' },
  { code: 'celebridade', name: 'Celebridade do campus', emoji: '🌟', tier: 'ouro', stat: 'likesReceived', target: 200, points: 150, desc: 'Receba 200 curtidas.' },
  { code: 'bom_de_papo', name: 'Bom de papo', emoji: '💬', tier: 'bronze', stat: 'commentsMade', target: 10, points: 30, desc: 'Faça 10 comentários.' },
  { code: 'apoiador', name: 'Apoiador', emoji: '👏', tier: 'bronze', stat: 'likesGiven', target: 25, points: 20, desc: 'Curta 25 publicações dos colegas.' },
  { code: 'reconhecido', name: 'Reconhecido', emoji: '🎖️', tier: 'bronze', stat: 'medals', target: 1, points: 25, desc: 'Receba sua primeira medalha de um professor.' },
  { code: 'colecionador', name: 'Colecionador', emoji: '🗃️', tier: 'prata', stat: 'medals', target: 5, points: 75, desc: 'Receba 5 medalhas.' },
  { code: 'versatil', name: 'Versátil', emoji: '🌈', tier: 'prata', stat: 'medalTypes', target: 3, points: 60, desc: 'Receba 3 tipos diferentes de medalha.' },
  { code: 'lenda', name: 'Lenda da UniMax', emoji: '🏆', tier: 'ouro', stat: 'medals', target: 15, points: 200, desc: 'Receba 15 medalhas.' },
  { code: 'cartao_de_visitas', name: 'Cartão de visitas', emoji: '🪪', tier: 'bronze', stat: 'profile', target: 1, points: 15, desc: 'Coloque foto de perfil e uma bio.' },
];
export const TROPHY_BY_CODE = Object.fromEntries(TROPHIES.map((t) => [t.code, t]));

export const POINT_RULES = [
  { emoji: '📸', text: `Publicar uma foto: +${POINTS.post} pts (até ${POINTS.postsPerDay} por dia)` },
  { emoji: '❤️', text: `Cada curtida recebida de um colega: +${POINTS.likeReceived} pts` },
  { emoji: '🎖️', text: 'Medalha dada por professor: de +20 a +100 pts, conforme o tipo' },
  { emoji: '🏆', text: 'Troféu desbloqueado: de +15 a +200 pts' },
];

