// Regras de negócio: publicar, curtir, comentar, dar medalha, troféus, pontos e ranking.
import { q, one } from './db.js';
import { POINTS, MEDAL_BY_CODE, TROPHIES, TROPHY_BY_CODE } from './rules.js';
import { startOfTodayBR, startOfMonthBR } from './config.js';

export class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

// ---------- Imagens ----------
const ALLOWED_MIME = ['image/jpeg', 'image/png', 'image/webp'];
const MAX_IMAGE_BYTES = 4 * 1024 * 1024;

export async function saveImageFromDataUrl(dataUrl, ownerId) {
  const m = /^data:([a-z/+-]+);base64,(.+)$/i.exec(String(dataUrl || ''));
  if (!m) throw new HttpError(400, 'Imagem inválida.');
  const mime = m[1].toLowerCase();
  if (!ALLOWED_MIME.includes(mime)) throw new HttpError(400, 'Formato de imagem não suportado. Use JPG, PNG ou WEBP.');
  const buf = Buffer.from(m[2], 'base64');
  if (buf.length === 0) throw new HttpError(400, 'Imagem vazia.');
  if (buf.length > MAX_IMAGE_BYTES) throw new HttpError(413, 'Imagem muito grande (máx. 4 MB).');
  return saveImage(mime, buf, ownerId);
}

export async function saveImage(mime, buf, ownerId = null) {
  const row = await one('INSERT INTO images (mime, data, owner_id) VALUES ($1, $2, $3) RETURNING id', [mime, buf, ownerId]);
  return row.id;
}

// ---------- Pontos ----------
async function addPoints(userId, amount, kind, ref) {
  await q('INSERT INTO points (user_id, amount, kind, ref) VALUES ($1, $2, $3, $4)', [userId, amount, kind, ref]);
}

export async function totalPoints(userId, since = null) {
  const r = await one(
    'SELECT COALESCE(SUM(amount), 0)::int AS pts FROM points WHERE user_id = $1 AND ($2::timestamptz IS NULL OR created_at >= $2)',
    [userId, since],
  );
  return r.pts;
}

// ---------- Troféus ----------
export async function getStats(userId) {
  return one(
    `SELECT
      (SELECT count(*) FROM posts WHERE user_id = $1 AND kind = 'foto')::int AS posts,
      (SELECT count(*) FROM likes l JOIN posts p ON p.id = l.post_id WHERE p.user_id = $1 AND l.user_id <> $1)::int AS "likesReceived",
      (SELECT count(*) FROM comments WHERE user_id = $1)::int AS "commentsMade",
      (SELECT count(*) FROM likes WHERE user_id = $1)::int AS "likesGiven",
      (SELECT count(*) FROM medals WHERE student_id = $1)::int AS medals,
      (SELECT count(DISTINCT type) FROM medals WHERE student_id = $1)::int AS "medalTypes",
      (SELECT CASE WHEN avatar_id IS NOT NULL AND length(bio) > 0 THEN 1 ELSE 0 END FROM users WHERE id = $1)::int AS profile`,
    [userId],
  );
}

// Confere se o aluno desbloqueou algum troféu novo. Devolve a lista dos novos.
export async function checkTrophies(userId) {
  const user = await one('SELECT role FROM users WHERE id = $1', [userId]);
  if (!user || user.role !== 'aluno') return [];
  const stats = await getStats(userId);
  const have = new Set((await q('SELECT code FROM user_trophies WHERE user_id = $1', [userId])).map((r) => r.code));
  const unlocked = [];
  for (const t of TROPHIES) {
    if (have.has(t.code) || (stats[t.stat] || 0) < t.target) continue;
    const ins = await q(
      'INSERT INTO user_trophies (user_id, code) VALUES ($1, $2) ON CONFLICT DO NOTHING RETURNING code',
      [userId, t.code],
    );
    if (!ins.length) continue; // outra requisição chegou primeiro
    await addPoints(userId, t.points, 'trofeu', `trophy:${t.code}`);
    await q("INSERT INTO posts (user_id, kind, ref_code) VALUES ($1, 'trofeu', $2)", [userId, t.code]);
    unlocked.push(t);
  }
  return unlocked;
}

// ---------- Publicações ----------
export async function createPost(user, { image, caption }) {
  if (user.role !== 'aluno') throw new HttpError(403, 'Só alunos publicam fotos no feed.');
  caption = String(caption || '').trim().slice(0, 1000);
  const imageId = await saveImageFromDataUrl(image, user.id);
  const post = await one(
    "INSERT INTO posts (user_id, kind, image_id, caption) VALUES ($1, 'foto', $2, $3) RETURNING id",
    [user.id, imageId, caption],
  );
  const today = await one(
    "SELECT count(*)::int AS n FROM points WHERE user_id = $1 AND kind = 'post' AND created_at >= $2",
    [user.id, startOfTodayBR()],
  );
  const earned = today.n < POINTS.postsPerDay ? POINTS.post : 0;
  if (earned) await addPoints(user.id, earned, 'post', `post:${post.id}`);
  const trophies = await checkTrophies(user.id);
  return { id: post.id, earned, trophies };
}

export async function deletePost(user, postId) {
  const post = await one('SELECT * FROM posts WHERE id = $1', [postId]);
  if (!post) throw new HttpError(404, 'Publicação não encontrada.');
  if (post.kind !== 'foto') throw new HttpError(400, 'Conquistas não podem ser apagadas por aqui.');
  if (post.user_id !== user.id && user.role !== 'admin') throw new HttpError(403, 'Você não pode apagar esta publicação.');
  await q("DELETE FROM points WHERE ref = $1 OR ref LIKE $2", [`post:${postId}`, `like:${postId}:%`]);
  await q('DELETE FROM posts WHERE id = $1', [postId]);
  if (post.image_id) await q('DELETE FROM images WHERE id = $1', [post.image_id]);
}

export async function toggleLike(user, postId) {
  const post = await one('SELECT id, user_id FROM posts WHERE id = $1', [postId]);
  if (!post) throw new HttpError(404, 'Publicação não encontrada.');
  const removed = await q('DELETE FROM likes WHERE post_id = $1 AND user_id = $2 RETURNING post_id', [postId, user.id]);
  let liked;
  const ref = `like:${postId}:${user.id}`;
  if (removed.length) {
    liked = false;
    await q('DELETE FROM points WHERE ref = $1', [ref]);
  } else {
    liked = true;
    const ins = await q(
      'INSERT INTO likes (post_id, user_id) VALUES ($1, $2) ON CONFLICT DO NOTHING RETURNING post_id',
      [postId, user.id],
    );
    if (ins.length && post.user_id !== user.id) {
      const owner = await one('SELECT role FROM users WHERE id = $1', [post.user_id]);
      if (owner?.role === 'aluno') await addPoints(post.user_id, POINTS.likeReceived, 'curtida', ref);
    }
    await checkTrophies(post.user_id);
    await checkTrophies(user.id);
  }
  const c = await one('SELECT count(*)::int AS n FROM likes WHERE post_id = $1', [postId]);
  return { liked, likes: c.n };
}

export async function addComment(user, postId, body) {
  body = String(body || '').trim().slice(0, 500);
  if (!body) throw new HttpError(400, 'Escreva alguma coisa.');
  const post = await one('SELECT id FROM posts WHERE id = $1', [postId]);
  if (!post) throw new HttpError(404, 'Publicação não encontrada.');
  const c = await one(
    'INSERT INTO comments (post_id, user_id, body) VALUES ($1, $2, $3) RETURNING id, created_at',
    [postId, user.id, body],
  );
  await checkTrophies(user.id);
  return c;
}

export async function deleteComment(user, commentId) {
  const c = await one(
    'SELECT c.*, p.user_id AS post_owner FROM comments c JOIN posts p ON p.id = c.post_id WHERE c.id = $1',
    [commentId],
  );
  if (!c) throw new HttpError(404, 'Comentário não encontrado.');
  if (c.user_id !== user.id && c.post_owner !== user.id && user.role !== 'admin') {
    throw new HttpError(403, 'Você não pode apagar este comentário.');
  }
  await q('DELETE FROM comments WHERE id = $1', [commentId]);
}

// ---------- Medalhas ----------
const MEDALS_PER_DAY = 30;

export async function giveMedal(prof, { student_id, type, reason }) {
  if (prof.role !== 'professor' && prof.role !== 'admin') throw new HttpError(403, 'Só professores dão medalhas.');
  const medal = MEDAL_BY_CODE[type];
  if (!medal) throw new HttpError(400, 'Tipo de medalha inválido.');
  reason = String(reason || '').trim().slice(0, 300);
  if (!reason) throw new HttpError(400, 'Conte o motivo da medalha — o aluno vai ver.');
  const student = await one('SELECT id, role FROM users WHERE id = $1', [Number(student_id)]);
  if (!student || student.role !== 'aluno') throw new HttpError(400, 'Escolha um aluno.');
  const today = await one(
    'SELECT count(*)::int AS n FROM medals WHERE professor_id = $1 AND created_at >= $2',
    [prof.id, startOfTodayBR()],
  );
  if (today.n >= MEDALS_PER_DAY) throw new HttpError(429, `Limite de ${MEDALS_PER_DAY} medalhas por dia atingido.`);
  const row = await one(
    'INSERT INTO medals (student_id, professor_id, type, reason) VALUES ($1, $2, $3, $4) RETURNING id',
    [student.id, prof.id, type, reason],
  );
  await addPoints(student.id, medal.points, 'medalha', `medal:${row.id}`);
  await q("INSERT INTO posts (user_id, kind, ref_id) VALUES ($1, 'medalha', $2)", [student.id, row.id]);
  const trophies = await checkTrophies(student.id);
  return { id: row.id, points: medal.points, trophies };
}

export async function revokeMedal(user, medalId) {
  const m = await one('SELECT * FROM medals WHERE id = $1', [medalId]);
  if (!m) throw new HttpError(404, 'Medalha não encontrada.');
  if (m.professor_id !== user.id && user.role !== 'admin') throw new HttpError(403, 'Só quem deu a medalha pode retirá-la.');
  await q('DELETE FROM points WHERE ref = $1', [`medal:${medalId}`]);
  const posts = await q("SELECT id FROM posts WHERE kind = 'medalha' AND ref_id = $1", [medalId]);
  for (const p of posts) await q('DELETE FROM points WHERE ref LIKE $1', [`like:${p.id}:%`]);
  await q("DELETE FROM posts WHERE kind = 'medalha' AND ref_id = $1", [medalId]);
  await q('DELETE FROM medals WHERE id = $1', [medalId]);
}

// ---------- Ranking ----------
export async function ranking({ courseId = null, period = 'all' } = {}) {
  const since = period === 'month' ? startOfMonthBR() : null;
  return q(
    `SELECT u.id, u.name, u.avatar_id, u.is_guest, u.course_id, c.short AS course,
            COALESCE(SUM(p.amount), 0)::int AS points
       FROM users u
       LEFT JOIN courses c ON c.id = u.course_id
       LEFT JOIN points p ON p.user_id = u.id AND ($1::timestamptz IS NULL OR p.created_at >= $1)
      WHERE u.role = 'aluno' AND ($2::int IS NULL OR u.course_id = $2)
      GROUP BY u.id, c.short
      ORDER BY points DESC, u.name ASC`,
    [since, courseId],
  );
}

export async function positions(user) {
  if (user.role !== 'aluno') return { general: null, course: null };
  const all = await ranking();
  const general = all.findIndex((r) => r.id === user.id) + 1 || null;
  const sameCourse = all.filter((r) => r.course_id === user.course_id);
  const course = sameCourse.findIndex((r) => r.id === user.id) + 1 || null;
  return { general, course, totalGeneral: all.length, totalCourse: sameCourse.length };
}

export { TROPHY_BY_CODE };

