// Teste automático do fluxo principal. Uso: npm test
// Sobe o servidor com um banco em memória (não mexe nos seus dados).
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';

process.env.DATABASE_URL = '';
delete process.env.DATABASE_URL;

const { createApp } = await import('../server/index.js');
const { closeDb } = await import('../server/db.js');

let server;
let base;

before(async () => {
  const app = await createApp({ dataDir: 'memory' });
  await new Promise((resolve) => { server = app.listen(0, resolve); });
  base = `http://127.0.0.1:${server.address().port}`;
});

after(async () => {
  server?.close();
  await closeDb();
});

function client() {
  let cookie = '';
  return async (path, { method = 'GET', body } = {}) => {
    const res = await fetch(base + path, {
      method,
      headers: { ...(body ? { 'Content-Type': 'application/json' } : {}), ...(cookie ? { Cookie: cookie } : {}) },
      body: body ? JSON.stringify(body) : undefined,
    });
    const set = res.headers.get('set-cookie');
    if (set) cookie = set.split(';')[0];
    const data = await res.json().catch(() => ({}));
    return { status: res.status, data };
  };
}

// PNG 1x1 válido.
const PNG = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==';

test('config pública e dados de exemplo', async () => {
  const api = client();
  const { data } = await api('/api/config');
  assert.ok(data.courses.length >= 5);
  assert.equal(data.bancaEnabled, true);
  assert.ok(data.medalTypes.length >= 5);
  const feed = await api('/api/feed');
  assert.equal(feed.status, 401, 'feed exige login');
});

test('cadastro só aceita e-mail da UniMax e professor precisa de código', async () => {
  const api = client();
  const { data: cfg } = await api('/api/config');
  const bad = await api('/api/auth/register', { method: 'POST', body: { name: 'Fulano Silva', email: 'fulano@gmail.com', password: '123456', role: 'aluno', course_id: cfg.courses[0].id } });
  assert.equal(bad.status, 400);
  const prof = await api('/api/auth/register', { method: 'POST', body: { name: 'Prof Falso', email: 'falso@unimax.edu.br', password: '123456', role: 'professor', professorCode: 'errado' } });
  assert.equal(prof.status, 400);
  const ok = await api('/api/auth/register', { method: 'POST', body: { name: 'Aluna Nova', email: 'aluna.nova@aluno.unimax.edu.br', password: '123456', role: 'aluno', course_id: cfg.courses[0].id, semester: 2 } });
  assert.equal(ok.status, 200);
  const me = await api('/api/me');
  assert.equal(me.data.user.name, 'Aluna Nova');
});

test('login com conta de exemplo', async () => {
  const api = client();
  const wrong = await api('/api/auth/login', { method: 'POST', body: { email: 'ana.souza@aluno.unimax.edu.br', password: 'x' } });
  assert.equal(wrong.status, 401);
  const ok = await api('/api/auth/login', { method: 'POST', body: { email: 'ana.souza@aluno.unimax.edu.br', password: 'maxx123' } });
  assert.equal(ok.status, 200);
});

test('fluxo da banca: aluno publica, professor dá medalha, ranking muda', async () => {
  const { data: cfg } = await client()('/api/config');
  const aluno = client();
  const wrongCode = await aluno('/api/auth/banca', { method: 'POST', body: { name: 'Banca A', role: 'aluno', course_id: cfg.courses[0].id, code: 'nope' } });
  assert.equal(wrongCode.status, 400);
  const login = await aluno('/api/auth/banca', { method: 'POST', body: { name: 'Banca A', role: 'aluno', course_id: cfg.courses[0].id, code: 'BANCA2026' } });
  assert.equal(login.status, 200);
  const { data: me } = await aluno('/api/me');
  assert.equal(me.user.is_guest, true);

  const post = await aluno('/api/posts', { method: 'POST', body: { image: PNG, caption: 'Olá banca!' } });
  assert.equal(post.status, 200);
  assert.equal(post.data.earned, 10);
  assert.ok(post.data.trophies.some((t) => t.code === 'primeiro_clique'), 'ganha troféu do primeiro post');

  const bad = await aluno('/api/posts', { method: 'POST', body: { image: 'data:image/svg+xml;base64,PHN2Zz4=', caption: 'x' } });
  assert.equal(bad.status, 400, 'não aceita SVG enviado por usuário');

  const prof = client();
  await prof('/api/auth/banca', { method: 'POST', body: { name: 'Banca B', role: 'professor', code: 'banca2026' } });
  const like = await prof(`/api/posts/${post.data.id}/like`, { method: 'POST' });
  assert.deepEqual(like.data, { liked: true, likes: 1 });
  const comment = await prof(`/api/posts/${post.data.id}/comments`, { method: 'POST', body: { body: 'Muito bom!' } });
  assert.equal(comment.status, 200);

  const studentPost = await aluno('/api/posts', { method: 'POST', body: { image: PNG, caption: '' } });
  assert.equal(studentPost.status, 200);
  const profPost = await prof('/api/posts', { method: 'POST', body: { image: PNG } });
  assert.equal(profPost.status, 403, 'professor não publica fotos');

  const medal = await prof('/api/medals', { method: 'POST', body: { student_id: me.user.id, type: 'excelencia', reason: 'Apresentação impecável' } });
  assert.equal(medal.status, 200);
  const noMedal = await aluno('/api/medals', { method: 'POST', body: { student_id: me.user.id, type: 'excelencia', reason: 'eu mesmo' } });
  assert.equal(noMedal.status, 403, 'aluno não dá medalha');

  // 10 + 10 (posts) + 2 (curtida) + 100 (medalha) + 15 (primeiro clique) + 25 (reconhecido)
  const { data: profile } = await aluno(`/api/users/${me.user.id}`);
  assert.equal(profile.points, 162);
  assert.ok(profile.positions.general >= 1);

  const { data: rk } = await aluno(`/api/ranking?course=${cfg.courses[0].id}`);
  assert.ok(rk.ranking.some((r) => r.id === me.user.id));

  const { data: ach } = await aluno(`/api/achievements/${me.user.id}`);
  assert.equal(ach.trophies.find((t) => t.code === 'reconhecido').unlocked, true);
  assert.equal(ach.medalTypes.find((m) => m.code === 'excelencia').count, 1);

  // Descurtir e retirar medalha devolvem os pontos.
  await prof(`/api/posts/${post.data.id}/like`, { method: 'POST' });
  await prof(`/api/medals/${medal.data.id}`, { method: 'DELETE' });
  const { data: after2 } = await aluno(`/api/users/${me.user.id}`);
  assert.equal(after2.points, 60);

  const { data: feed } = await aluno('/api/feed?limit=5');
  assert.ok(feed.posts.length > 0);
  const del = await prof(`/api/posts/${post.data.id}`, { method: 'DELETE' });
  assert.equal(del.status, 403, 'não apaga post dos outros');
});

test('mural de avisos', async () => {
  const prof = client();
  await prof('/api/auth/login', { method: 'POST', body: { email: 'helena.duarte@unimax.edu.br', password: 'maxx123' } });
  const n = await prof('/api/notices', { method: 'POST', body: { title: 'Prova', body: 'Prova na sexta.' } });
  assert.equal(n.status, 200);
  const aluno = client();
  await aluno('/api/auth/login', { method: 'POST', body: { email: 'juliana.martins@aluno.unimax.edu.br', password: 'maxx123' } });
  const { data } = await aluno('/api/notices');
  assert.ok(data.notices.some((x) => x.title === 'Prova'));
  const no = await aluno('/api/notices', { method: 'POST', body: { title: 'x', body: 'y' } });
  assert.equal(no.status, 403);
});

