// Login, senha e sessão (cookie).
import crypto from 'node:crypto';
import { q, one } from './db.js';
import { HttpError } from './services.js';

const COOKIE = 'maxx_session';

export function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.scryptSync(String(password), salt, 64).toString('hex');
  return `${salt}:${hash}`;
}

export function checkPassword(password, stored) {
  if (!stored || !stored.includes(':')) return false;
  const [salt, hash] = stored.split(':');
  const test = crypto.scryptSync(String(password), salt, 64);
  const ref = Buffer.from(hash, 'hex');
  return ref.length === test.length && crypto.timingSafeEqual(ref, test);
}

export async function createSession(res, req, userId, days = 30) {
  const token = crypto.randomBytes(32).toString('hex');
  const expires = new Date(Date.now() + days * 24 * 3600 * 1000);
  await q('INSERT INTO sessions (token, user_id, expires_at) VALUES ($1, $2, $3)', [token, userId, expires]);
  res.cookie(COOKIE, token, {
    httpOnly: true,
    sameSite: 'lax',
    secure: req.secure,
    expires,
    path: '/',
  });
}

export async function destroySession(req, res) {
  const token = readToken(req);
  if (token) await q('DELETE FROM sessions WHERE token = $1', [token]);
  res.clearCookie(COOKIE, { path: '/' });
}

function readToken(req) {
  const header = req.headers.cookie || '';
  for (const part of header.split(';')) {
    const [k, ...v] = part.trim().split('=');
    if (k === COOKIE) return decodeURIComponent(v.join('='));
  }
  return null;
}

export const PUBLIC_USER_FIELDS = 'u.id, u.name, u.role, u.course_id, u.semester, u.bio, u.avatar_id, u.is_guest, u.created_at';

// Middleware: coloca req.user se houver sessão válida.
export async function loadUser(req, _res, next) {
  const token = readToken(req);
  req.user = null;
  if (token) {
    req.user = await one(
      `SELECT ${PUBLIC_USER_FIELDS}, u.email, c.name AS course_name, c.short AS course
         FROM sessions s JOIN users u ON u.id = s.user_id LEFT JOIN courses c ON c.id = u.course_id
        WHERE s.token = $1 AND s.expires_at > now()`,
      [token],
    );
  }
  next();
}

export function requireUser(req, _res, next) {
  if (!req.user) throw new HttpError(401, 'Faça login para continuar.');
  next();
}

// Limite simples de tentativas (por IP) para login e cadastro.
const attempts = new Map();
export function rateLimit(max = 30, windowMs = 10 * 60 * 1000) {
  return (req, _res, next) => {
    const key = `${req.ip}:${req.path}`;
    const now = Date.now();
    const rec = attempts.get(key) || { n: 0, start: now };
    if (now - rec.start > windowMs) {
      rec.n = 0;
      rec.start = now;
    }
    rec.n += 1;
    attempts.set(key, rec);
    if (rec.n > max) throw new HttpError(429, 'Muitas tentativas. Espere alguns minutos e tente de novo.');
    next();
  };
}

