// Configurações que podem ser trocadas por variáveis de ambiente (no Render: aba "Environment").
const list = (v, def) => (v ?? def).split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);

export const config = {
  port: Number(process.env.PORT) || 3000,
  // Domínios de e-mail aceitos no cadastro. Só quem tem e-mail da UniMax consegue criar conta.
  emailDomains: list(process.env.EMAIL_DOMAINS, 'unimax.edu.br,aluno.unimax.edu.br'),
  // Código que o professor precisa digitar para se cadastrar como professor.
  professorCode: process.env.PROFESSOR_CODE || 'PROFESSOR-UNIMAX',
  // Acesso rápido da banca (sem cadastro). BANCA_ENABLED=false desliga.
  bancaEnabled: (process.env.BANCA_ENABLED || 'true').toLowerCase() !== 'false',
  // Código da banca. Vazio = não pede código.
  bancaCode: process.env.BANCA_CODE ?? 'banca2026',
  // Senha da conta da secretaria (admin) criada nos dados de exemplo.
  adminPassword: process.env.ADMIN_PASSWORD || 'admin-unimax',
  // Senha das contas de exemplo (alunos e professores fictícios).
  demoPassword: process.env.DEMO_PASSWORD || 'maxx123',
  // Cria dados de exemplo quando o banco está vazio.
  seedDemo: (process.env.SEED_DEMO || 'true').toLowerCase() !== 'false',
};

// Brasil não tem horário de verão desde 2019: UTC-3 fixo.
const BR_OFFSET_MS = 3 * 60 * 60 * 1000;

export function startOfTodayBR() {
  const now = new Date(Date.now() - BR_OFFSET_MS);
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()) + BR_OFFSET_MS);
}

export function startOfMonthBR() {
  const now = new Date(Date.now() - BR_OFFSET_MS);
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1) + BR_OFFSET_MS);
}

