1	// Login, senha e sessão (cookie).
2	import crypto from 'node:crypto';
3	import { q, one } from './db.js';
4	import { HttpError } from './services.js';
5	
6	const COOKIE = 'maxx_session';
7	
8	export function hashPassword(password) {
9	  const salt = crypto.randomBytes(16).toString('hex');
10	  const hash = crypto.scryptSync(String(password), salt, 64).toString('hex');
11	  return `${salt}:${hash}`;
12	}
13	
14	export function checkPassword(password, stored) {
15	  if (!stored || !stored.includes(':')) return false;
16	  const [salt, hash] = stored.split(':');
17	  const test = crypto.scryptSync(String(password), salt, 64);
18	  const ref = Buffer.from(hash, 'hex');
19	  return ref.length === test.length && crypto.timingSafeEqual(ref, test);
20	}
21	
22	export async function createSession(res, req, userId, days = 30) {
23	  const token = crypto.randomBytes(32).toString('hex');
24	  const expires = new Date(Date.now() + days * 24 * 3600 * 1000);
25	  await q('INSERT INTO sessions (token, user_id, expires_at) VALUES ($1, $2, $3)', [token, userId, expires]);
26	  res.cookie(COOKIE, token, {
27	    httpOnly: true,
28	    sameSite: 'lax',
29	    secure: req.secure,
30	    expires,
31	    path: '/',
32	  });
33	}
34	
35	export async function destroySession(req, res) {
36	  const token = readToken(req);
37	  if (token) await q('DELETE FROM sessions WHERE token = $1', [token]);
38	  res.clearCookie(COOKIE, { path: '/' });
39	}
40	
41	function readToken(req) {
42	  const header = req.headers.cookie || '';
43	  for (const part of header.split(';')) {
44	    const [k, ...v] = part.trim().split('=');
45	    if (k === COOKIE) return decodeURIComponent(v.join('='));
46	  }
47	  return null;
48	}
49	
50	export const PUBLIC_USER_FIELDS = 'u.id, u.name, u.role, u.course_id, u.semester, u.bio, u.avatar_id, u.is_guest, u.created_at';
51	
52	// Middleware: coloca req.user se houver sessão válida.
53	export async function loadUser(req, _res, next) {
54	  const token = readToken(req);
55	  req.user = null;
56	  if (token) {
57	    req.user = await one(
58	      `SELECT ${PUBLIC_USER_FIELDS}, u.email, c.name AS course_name, c.short AS course
59	         FROM sessions s JOIN users u ON u.id = s.user_id LEFT JOIN courses c ON c.id = u.course_id
60	        WHERE s.token = $1 AND s.expires_at > now()`,
61	      [token],
62	    );
63	  }
64	  next();
65	}
66	
67	export function requireUser(req, _res, next) {
68	  if (!req.user) throw new HttpError(401, 'Faça login para continuar.');
69	  next();
70	}
71	
72	// Limite simples de tentativas (por IP) para login e cadastro.
73	const attempts = new Map();
74	export function rateLimit(max = 30, windowMs = 10 * 60 * 1000) {
75	  return (req, _res, next) => {
76	    const key = `${req.ip}:${req.path}`;
77	    const now = Date.now();
78	    const rec = attempts.get(key) || { n: 0, start: now };
79	    if (now - rec.start > windowMs) {
80	      rec.n = 0;
81	      rec.start = now;
82	    }
83	    rec.n += 1;
84	    attempts.set(key, rec);
85	    if (rec.n > max) throw new HttpError(429, 'Muitas tentativas. Espere alguns minutos e tente de novo.');
86	    next();
87	  };
88	}
