1	// Camada de banco de dados.
2	// - Se a variável DATABASE_URL existir (ex.: banco gratuito no Neon), usa PostgreSQL de verdade.
3	// - Se não existir, usa o PGlite: um PostgreSQL embutido que salva tudo na pasta ./data.
4	// Os dois falam o mesmo SQL, então o resto do código não precisa saber qual está em uso.
5	import fs from 'node:fs';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	const here = path.dirname(fileURLToPath(import.meta.url));
10	let impl = null;
11	
12	export async function initDb({ dataDir } = {}) {
13	  if (impl) return impl;
14	  const url = process.env.DATABASE_URL;
15	  if (url) {
16	    const { default: pg } = await import('pg');
17	    const local = /localhost|127\.0\.0\.1/.test(url);
18	    const pool = new pg.Pool({
19	      connectionString: url,
20	      ssl: local ? false : { rejectUnauthorized: false },
21	      max: 5,
22	    });
23	    impl = {
24	      kind: 'postgres',
25	      query: (sql, params) => pool.query(sql, params),
26	      exec: (sql) => pool.query(sql),
27	      close: () => pool.end(),
28	    };
29	  } else {
30	    const { PGlite } = await import('@electric-sql/pglite');
31	    const dir = dataDir || process.env.DATA_DIR || path.join(here, '..', 'data', 'pglite');
32	    if (dir !== 'memory') fs.mkdirSync(dir, { recursive: true });
33	    const db = dir === 'memory' ? await PGlite.create() : await PGlite.create(dir);
34	    impl = {
35	      kind: 'pglite',
36	      query: (sql, params) => db.query(sql, params),
37	      exec: (sql) => db.exec(sql),
38	      close: () => db.close(),
39	    };
40	  }
41	  const schema = fs.readFileSync(path.join(here, 'schema.sql'), 'utf8');
42	  await impl.exec(schema);
43	  return impl;
44	}
45	
46	export async function q(sql, params = []) {
47	  const res = await impl.query(sql, params);
48	  return res.rows;
49	}
50	
51	export async function one(sql, params = []) {
52	  const rows = await q(sql, params);
53	  return rows[0] || null;
54	}
55	
56	export async function closeDb() {
57	  if (impl) {
58	    await impl.close();
59	    impl = null;
60	  }
61	}
62	
63	export function dbKind() {
64	  return impl ? impl.kind : null;
65	}
