22	// Brasil não tem horário de verão desde 2019: UTC-3 fixo.
23	const BR_OFFSET_MS = 3 * 60 * 60 * 1000;
24	
25	export function startOfTodayBR() {
26	  const now = new Date(Date.now() - BR_OFFSET_MS);
27	  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()) + BR_OFFSET_MS);
28	}
29	
30	export function startOfMonthBR() {
31	  const now = new Date(Date.now() - BR_OFFSET_MS);
32	  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1) + BR_OFFSET_MS);
33	}
